mapper.sql:
WHERE u.deleted = 0

    AND u.status = #{status}


    AND (
        IFNULL(u.username, '') LIKE CONCAT('%', #{keyword}, '%')
        OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%')
    )

mapper.insert:
INSERT INTO sys_user (
    username, nickname, password_hash, signature, status, deleted
) VALUES (
    #{username}, #{nickname}, #{passwordHash}, #{signature}, #{status}, 0
)

mapper.update:
UPDATE sys_user
SET status = #{status}
WHERE id = #{id}
  AND deleted = 0

UPDATE sys_user
SET password_hash = #{passwordHash}
WHERE id = #{id}
  AND deleted = 0
